				reader:     reader,
				proxyLine:  proxyLine,
				clientAddr: clientAddr,
			}, nil
		case ProtoTLS, ProtoHTTP:
			return &Conn{
				protocol:  proto,
				Conn:      conn,
				reader:    reader,
				proxyLine: proxyLine,
			}, nil
		case ProtoPostgres:
			return &Conn{
				protocol: proto,
				Conn:     conn,
		if err != nil {
			return ProtoUnknown, trace.Wrap(err, "failed to peek connection")
		}
